source5='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    ref=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==4]
    if not ref: return out
    r0,c0=min(r for r,c in ref),min(c for r,c in ref)
    shape={(r-r0,c-c0) for r,c in ref}
    for color in set(v for row in grid for v in row)-{1,4}:
        unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]==color}
        while unseen:
            seed=min(unseen); unseen.remove(seed); stack=[seed]; comp=[seed]
            while stack:
                r,c=stack.pop()
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        q=(r+dr,c+dc)
                        if (dr or dc) and q in unseen:
                            unseen.remove(q); stack.append(q); comp.append(q)
            offsets={(r-dr,c-dc) for r,c in comp for dr,dc in shape}
            valid=sorted((ar,ac) for ar,ac in offsets if all((r-ar,c-ac) in shape for r,c in comp))
            if not valid: continue
            ar,ac=valid[0]
            for dr,dc in shape:
                rr,cc=ar+dr,ac+dc
                if 0<=rr<h and 0<=cc<w: out[rr][cc]=color
    return out
